        right.Children.Add(_privateMetadata);Label(_privateMetadata,"Declared current camera identity",CameraIdInput);Label(_privateMetadata,"Reviewer",ReviewerInput);Label(_privateMetadata,"Reason / revision notes",ReasonInput);Label(right,"Profile revision",RevisionInput);
        var tolerances=new UniformGrid{Columns=2};Label(tolerances,"Control tolerance (cm)",ControlToleranceInput);Label(tolerances,"Independent check tolerance (cm)",CheckToleranceInput);Label(tolerances,"Max camera translation (px)",TranslationToleranceInput);Label(tolerances,"Max residual (px)",ResidualToleranceInput);right.Children.Add(tolerances);
