    private void SetupGrid(DataGrid grid,bool measured){grid.AutoGenerateColumns=false;grid.CanUserAddRows=false;grid.CanUserDeleteRows=true;grid.Columns.Add(new DataGridTextColumn{Header=_blind?"Opaque marker":"Marker ID",IsReadOnly=_blind,Binding=new System.Windows.Data.Binding(_blind?nameof(CameraLandmarkRow.BlindLabel):nameof(CameraLandmarkRow.Id))});grid.Columns.Add(new DataGridTextColumn{Header="Image X (px)",Binding=new System.Windows.Data.Binding(nameof(CameraLandmarkRow.ImageX))});grid.Columns.Add(new DataGridTextColumn{Header="Image Y (px)",Binding=new System.Windows.Data.Binding(nameof(CameraLandmarkRow.ImageY))});if(measured){grid.Columns.Add(new DataGridTextColumn{Header="Room X (cm)",Binding=new System.Windows.Data.Binding(nameof(CameraLandmarkRow.RoomXcm))});grid.Columns.Add(new DataGridTextColumn{Header="Room Y (cm)",Binding=new System.Windows.Data.Binding(nameof(CameraLandmarkRow.RoomYcm))});grid.Columns.Add(new DataGridCheckBoxColumn{Header="Independent",Binding=new System.Windows.Data.Binding(nameof(CameraLandmarkRow.IndependentCheck))});}}
    private VideoAsset Current()=>_service.Store.Videos().Single(a=>a.Id==_videoId);
    public async Task LoadFrameAsync()
    {
        var generation=++_generation;DisplayedFrame=null;DisplayedBitmap=null;SourceImage.Source=null;Invalidate("Loading exact verified source frame…");
        try
        {
            var asset=Current();var frame=FrameIdentity.RequireSourceFrame(int.Parse(FrameInput.Text,CultureInfo.InvariantCulture),asset.Metadata.FrameCount);
            var bytes=await Task.Run(()=>_decoder.Read(asset.Path,frame,expectedSha256:asset.SourceSha256));if(_disposed || generation!=_generation)return;
            var bitmap=CameraFrameMaterial.Bitmap(bytes);if(bitmap.PixelWidth!=asset.Metadata.Width || bitmap.PixelHeight!=asset.Metadata.Height)throw new InvalidDataException("Displayed resolution differs from registration.");
            DisplayedBitmap=bitmap;DisplayedFrame=new(asset.Id,asset.SourceSha256,frame,bitmap.PixelWidth,bitmap.PixelHeight,CameraFrameMaterial.BytesHash(bytes),CameraFrameMaterial.PixelHash(bitmap));SourceImage.Source=bitmap;var plane=(Grid)((Viewbox)SourceViewport.Child).Child;plane.Width=bitmap.PixelWidth;plane.Height=bitmap.PixelHeight;SourceOverlay.Width=bitmap.PixelWidth;SourceOverlay.Height=bitmap.PixelHeight;
            _identity.Text=_blind?$"Exact frame {frame} • {bitmap.PixelWidth}×{bitmap.PixelHeight} • software source identifiers held; pixels are not automatically redacted.":$"Exact frame {frame} • {bitmap.PixelWidth}×{bitmap.PixelHeight} • source {asset.SourceSha256[..12]} • displayed pixels {DisplayedFrame.DisplayedPixelSha256[..12]}";_status.Text="Select a row and click a landmark, or enter measured source pixels/room cm. Independent checks are separate from fitting controls.";DrawMarkers();
        }
        catch(Exception ex){Hold(ex);}
    }
    private string FrameKey()=>JsonDefaults.Serialize(RequireShown());
    private CameraFrameIdentity RequireShown(){var frame=DisplayedFrame??throw new InvalidOperationException("Exact source pixels are not ready.");if(frame.Frame!=int.Parse(FrameInput.Text,CultureInfo.InvariantCulture))throw new InvalidOperationException("Frame request differs from displayed pixels.");return frame;}
    public CameraLandmarkRow AddLandmark(bool check){if(Landmarks.Count>=128)throw new InvalidOperationException("Landmark budget is 128.");var row=new CameraLandmarkRow{Id=(check?"Q":"C")+(Landmarks.Count+1),IndependentCheck=check,Origin=FrameKey(),BlindLabel="Point "+(Landmarks.Count+1)};row.PropertyChanged+=(_,_)=>{_fit=null;Invalidate("Measured inputs changed; refit/save a new immutable revision.");DrawMarkers();};Landmarks.Add(row);LandmarkGrid.SelectedItem=row;return row;}
    public CameraLandmarkRow AddMarker(){if(ObservedMarkers.Count>=128)throw new InvalidOperationException("Stationary marker budget is 128.");var row=new CameraLandmarkRow{Id="C"+(ObservedMarkers.Count+1),Origin=FrameKey(),BlindLabel="Marker "+(ObservedMarkers.Count+1)};row.PropertyChanged+=(_,_)=>{Invalidate("Stationary observation changed; recheck/reassign.");DrawMarkers();};ObservedMarkers.Add(row);MarkerGrid.SelectedItem=row;return row;}
    public void PickAtViewport(double x,double y)
    {
        var frame=RequireShown();var point=DisplayToVideo.MapDips(x,y,SourceViewport.ActualWidth,SourceViewport.ActualHeight,frame.Width,frame.Height)??throw new ArgumentException("Click is outside the displayed source image (letterbox).");
        var row=(Editors.SelectedIndex==0?LandmarkGrid.SelectedItem:Editors.SelectedIndex==1?MarkerGrid.SelectedItem:null) as CameraLandmarkRow??throw new InvalidOperationException("Select the landmark/observation row to place.");if(row.Origin!=FrameKey())throw new InvalidOperationException("Row belongs to another source frame; start a new measured draft.");row.ImageX=Math.Floor(point.X);row.ImageY=Math.Floor(point.Y);
    }
    private void DrawMarkers(){SourceOverlay.Children.Clear();foreach(var row in Landmarks.Concat(ObservedMarkers)){var marker=new Ellipse{Width=6,Height=6,Stroke=row.IndependentCheck?Brushes.LimeGreen:Brushes.Orange,StrokeThickness=1,Tag=_blind?row.BlindLabel:row.Id};Canvas.SetLeft(marker,row.ImageX-3);Canvas.SetTop(marker,row.ImageY-3);SourceOverlay.Children.Add(marker);}}
    private void CommitEdits(){LandmarkGrid.CommitEdit(DataGridEditingUnit.Cell,true);LandmarkGrid.CommitEdit(DataGridEditingUnit.Row,true);MarkerGrid.CommitEdit(DataGridEditingUnit.Cell,true);MarkerGrid.CommitEdit(DataGridEditingUnit.Row,true);}
    private CalibrationRequest Request(){CommitEdits();var frame=RequireShown();if(Landmarks.Any(p=>p.Origin!=FrameKey()))throw new InvalidOperationException("Measured rows belong to another frame; clear and measure the current frame explicitly.");MeasuredLandmark Convert(CameraLandmarkRow p)=>new(p.Id.Trim(),new(p.ImageX,p.ImageY),new(p.RoomXcm,p.RoomYcm));return new(CameraIdInput.Text.Trim(),frame.Width,frame.Height,frame.SourceSha256,frame.Frame,int.Parse(RevisionInput.Text,CultureInfo.InvariantCulture),Landmarks.Where(p=>!p.IndependentCheck).Select(Convert).ToImmutableArray(),Landmarks.Where(p=>p.IndependentCheck).Select(Convert).ToImmutableArray(),Number(ControlToleranceInput),Number(CheckToleranceInput),WaterPlaneInput.IsChecked==true,ReviewerInput.Text.Trim());}
    private CameraObservation Observation(){CommitEdits();var frame=RequireShown();if(ObservedMarkers.Any(p=>p.Origin!=FrameKey()))throw new InvalidOperationException("Stationary observations belong to another frame.");return new(CameraIdInput.Text.Trim(),frame.Width,frame.Height,frame.SourceSha256,frame.Frame,StationaryInput.IsChecked==true,ObservedMarkers.Select(p=>new FiducialObservation(p.Id.Trim(),new(p.ImageX,p.ImageY))).ToImmutableArray());}
    private ShiftTolerances Tolerances()=>new(Number(TranslationToleranceInput),Number(ResidualToleranceInput));
    private static double Number(TextBox box){if(!double.TryParse(box.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out var value)||!double.IsFinite(value))throw new ArgumentException("Supply finite numerical values (decimal point).");return value;}
    private void Fit(){_fit=null;if(PrespecifiedInput.IsChecked!=true)throw new InvalidOperationException("Confirm prespecified tolerances before fitting.");_fit=WaterPlaneCalibration.Fit(Request());_status.Text=(_fit.EligibleForMeasuredCoordinates?"Measured-input fit/check gates passed; real-data accuracy remains unvalidated. ":"Physical use HELD: "+string.Join(" ",_fit.HoldReasons))+string.Join("; ",_fit.Residuals.Select(p=>$"{p.Id} {(p.IndependentCheck?"independent":"control")} error {p.ErrorCm:G6} cm"));}
    private void SaveProfile(){var fit=_fit??throw new InvalidOperationException("Fit current measured inputs first.");if(fit.Id!=WaterPlaneCalibration.Fit(Request()).Id)throw new InvalidOperationException("Profile draft changed; refit.");var row=_service.SaveProfile(fit,RequireShown(),ReviewerInput.Text,ReasonInput.Text,PrespecifiedInput.IsChecked==true);RefreshChoices(row.Id,null);_status.Text="Immutable measured inputs/profile saved in the study database. "+(fit.EligibleForMeasuredCoordinates?"Select stationary current-frame checks and explicitly Assign.":"Held profile cannot produce physical coordinates.");}
    private void SavePreset(){var row=_service.SavePreset(PresetNameInput.Text,CameraIdInput.Text.Trim(),RequireShown(),Observation(),ReadDetector(),ReviewerInput.Text,ReasonInput.Text);RefreshChoices(null,row.Id);_status.Text="Detector/geometry preset saved. Target intervals and biological protocol are excluded.";}
    private void Preview(){_preview=_service.Preview(SelectedPresetRow??throw new InvalidOperationException("Select a preset."),_videoId,RequireShown(),Observation(),Tolerances());ApplyConfirmedInput.IsChecked=false;_status.Text=_preview.Difference+(_preview.Compatible?" Camera checks passed; explicit confirmation still required.":" HELD: "+string.Join(" ",_preview.Holds));}
    private void Apply(){var preview=_preview??throw new InvalidOperationException("Preview this preset first.");_service.Apply(preview,RequireShown(),Observation(),Tolerances(),ReviewerInput.Text,ReasonInput.Text,ApplyConfirmedInput.IsChecked==true,_saveSettings);_preview=null;Invalidate("Preset applied through audited settings storage. Raw runs/source/biological protocol unchanged; stale analysis/review require reanalysis.");}
    private void Assign(){_service.Assign(SelectedProfileRow??throw new InvalidOperationException("Select a measured profile."),RequireShown(),Observation(),Tolerances(),ReviewerInput.Text,ReasonInput.Text,LimitsInput.IsChecked==true && WaterPlaneInput.IsChecked==true);Invalidate("Camera checks/profile assigned to current source/settings/run/corrections. Generate room-cm output after current tracking review.");}
    private void EnsureAssignedDraft(){var row=_service.History.Read("assignment",_videoId).LastOrDefault()??throw new InvalidOperationException("No profile assignment.");var assignment=JsonDefaults.Deserialize<CameraAssignment>(row.Json);if(SelectedProfileRow?.Id!=assignment.ProfileRowId || JsonDefaults.Serialize(Observation())!=JsonDefaults.Serialize(assignment.Observation) || JsonDefaults.Serialize(Tolerances())!=JsonDefaults.Serialize(assignment.Tolerances) || JsonDefaults.Serialize(RequireShown())!=JsonDefaults.Serialize(assignment.ObservedFrame) || LimitsInput.IsChecked!=true || WaterPlaneInput.IsChecked!=true)throw new InvalidOperationException("Camera/profile/check draft differs from assigned evidence. Recheck and assign a new revision.");}
    private void Derive(){EnsureAssignedDraft();var output=_service.Derive(_videoId);if(!output.Holds.IsEmpty)throw new InvalidOperationException(string.Join(" ",output.Holds));PhysicalOutput=output;PhysicalGrid.ItemsSource=output.Frames;_derived.Text=$"MEASURED ROOM cm — adjacent corrected path {output.AdjacentPathCm:G6} cm; explicit unknown time {output.UnknownSeconds:G6} s. Target alignment is not applied.\n"+output.Scope;_derivedRevision=CameraRunSnapshot.Read(_service.Store.DatabasePath,_videoId).Revision;_derivedAssignmentId=output.AssignmentRowId;_derivedProfileCatalog=ProfileCatalogRevision();_status.Text="Physical derived rows generated from the assigned immutable model; no raw/trial measurements were overwritten.";}
    private string ProfileCatalogRevision()=>CameraHistoryStore.Digest(string.Join("|",_service.History.Read("profile").Select(r=>r.Id+":"+r.ContentSha256)));
    private void Invalidate(string text){_preview=null;ApplyConfirmedInput.IsChecked=false;PhysicalOutput=null;PhysicalGrid.ItemsSource=null;_derivedRevision=null;_derived.Text="Physical output held / not generated: "+text;}
    private void Hold(Exception ex){Invalidate(_blind?"Camera integrity check held; verify source and calibration declarations.":ex.Message);_status.Text=_blind?"Camera setup held; inspect integrity.":ex.Message;}
    private void Run(Action action){try{if(_disposed)throw new ObjectDisposedException(nameof(CameraCalibrationWindow));action();if(_blind)_status.Text=_fit is{}fit?((fit.EligibleForMeasuredCoordinates?"Fit/check gates passed. ":"Physical calibration use held. ")+"Software marker identities and notes are held; pixels are not redacted."):"Operation processed. Setup identities/notes remain held; source pixels are not redacted.";}catch(Exception ex){Hold(ex);}}
    private static int Integer(TextBox input){var value=Number(input);if(value!=Math.Truncate(value))throw new ArgumentException("Detector integer fields cannot be silently rounded.");return checked((int)value);}
    private void FillDetector(TrackingSettings s){foreach(var pair in new[]{("threshold",(double)s.Threshold),("blur",(double)s.Blur),("min",s.MinArea),("max",s.MaxArea),("extent",(double)s.MaxExtension),("jump",s.MaxJump),("cx",s.Cx),("cy",s.Cy),("rx",s.Rx),("ry",s.Ry)})_detector[pair.Item1].Text=pair.Item2.ToString("G17",CultureInfo.InvariantCulture);_detector["diameter"].Text=s.DiameterCm?.ToString("G17",CultureInfo.InvariantCulture)??"";}
    public TextBox DetectorInput(string key)=>_detector[key];
    private TrackingSettings ReadDetector(){var current=Current().Settings;return current with{Threshold=Integer(_detector["threshold"]),Blur=Integer(_detector["blur"]),MinArea=Number(_detector["min"]),MaxArea=Number(_detector["max"]),MaxExtension=Integer(_detector["extent"]),MaxJump=Number(_detector["jump"]),Cx=Number(_detector["cx"]),Cy=Number(_detector["cy"]),Rx=Number(_detector["rx"]),Ry=Number(_detector["ry"]),DiameterCm=string.IsNullOrWhiteSpace(_detector["diameter"].Text)?null:Number(_detector["diameter"])};}
    private void RefreshChoices(string? profileId=null,string? presetId=null){ProfileChoice.Items.Clear();PresetChoice.Items.Clear();var profileNumber=0;var presetNumber=0;foreach(var row in _service.History.Read()){if(row.Kind=="profile"){var p=JsonDefaults.Deserialize<CameraProfileEvidence>(row.Json);var item=new ComboBoxItem{Content=_blind?"Profile "+(++profileNumber):"Profile "+p.ProfileId[..10],Tag=row};ProfileChoice.Items.Add(item);if(row.Id==profileId)ProfileChoice.SelectedItem=item;}else if(row.Kind=="preset"){var p=JsonDefaults.Deserialize<DetectorGeometryPreset>(row.Json);var item=new ComboBoxItem{Content=_blind?"Preset "+(++presetNumber):p.Name,Tag=row};PresetChoice.Items.Add(item);if(row.Id==presetId)PresetChoice.SelectedItem=item;}}}
    private void UpdateDisclosure()
    {
        _privateMetadata.Visibility=_blind?Visibility.Collapsed:Visibility.Visible;
        _blindNotice.Text=_blind?"Blinded setup: software source/camera/preset identities and free notes are held. Source pixels are not automatically redacted.":"Setup software metadata is visible in this window. Source pixels are not automatically redacted.";
        RevealMetadataButton.Visibility=_blind?Visibility.Visible:Visibility.Collapsed;
        foreach(var grid in new[]{LandmarkGrid,MarkerGrid}){var column=(DataGridTextColumn)grid.Columns[0];column.Header=_blind?"Opaque marker":"Marker ID";column.IsReadOnly=_blind;column.Binding=new System.Windows.Data.Binding(_blind?nameof(CameraLandmarkRow.BlindLabel):nameof(CameraLandmarkRow.Id));}
        if(_blind)_identity.Text=DisplayedFrame is{}frame?$"Exact frame {frame.Frame} • {frame.Width}×{frame.Height} • software identifiers held.":"Load exact source pixels. Software identifiers held.";
    }
    public bool TryRevealMetadata(string reviewer,string reason)
    {
        try
        {
            if(string.IsNullOrWhiteSpace(reviewer)||string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Reviewer and reason are required for metadata reveal.");
            _service.Store.Audit("camera_setup_metadata_revealed",new{VideoId=_videoId,Reviewer=reviewer.Trim(),Reason=reason.Trim(),Scope="This camera setup window only; pixels are not automatically redacted."});
            _blind=false;UpdateDisclosure();RefreshChoices();DrawMarkers();_status.Text="Setup metadata reveal audited. Main review blinding remains independent.";return true;
        }
        catch(Exception){_status.Text="Metadata reveal failed or was not confirmed; blind state remains unchanged.";return false;}
    }
    public void Dispose(){if(_disposed)return;_disposed=true;_generation++;_freshness.Stop();_decoder.Dispose();DisplayedFrame=null;DisplayedBitmap=null;SourceImage.Source=null;}
